package com.ilia.gikashvili.archmain.search.service;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.ilia.gikashvili.archmain.project.repository.ProjectRepository;import com.ilia.gikashvili.archmain.architecture.service.ArchitectureService;import com.ilia.gikashvili.archmain.review.repository.ReviewFindingRepository;import com.ilia.gikashvili.archmain.access.service.ProjectAccessService;import com.ilia.gikashvili.archmain.access.policy.Permission;
@Service @Transactional(readOnly=true) public class SearchService {private final ProjectRepository projects;private final ArchitectureService architecture;private final ReviewFindingRepository findings;private final ProjectAccessService access;public SearchService(ProjectRepository p,ArchitectureService a,ReviewFindingRepository f,ProjectAccessService s){projects=p;architecture=a;findings=f;access=s;}
public record Result(String kind,String id,UUID projectId,String label,String description){}
private String query(String q){if(q==null||q.isBlank()||q.length()>200)throw new com.ilia.gikashvili.archmain.common.exception.ValidationException("Query must contain 1-200 characters");return q.trim().toLowerCase(Locale.ROOT);}
private boolean matches(String q,String... values){return Arrays.stream(values).filter(Objects::nonNull).anyMatch(s->s.toLowerCase(Locale.ROOT).contains(q));}
public List<Result> global(UUID uid,String term){String q=query(term);return projects.findAccessibleByUserId(uid).stream().filter(p->matches(q,p.getName(),p.getDescription())).map(p->new Result("project",p.getId().toString(),p.getId(),p.getName(),p.getDescription())).toList();}
public List<Result> project(UUID uid,UUID pid,String term){String q=query(term);access.require(pid,uid,Permission.READ);var d=architecture.getDocument(pid,uid);var r=new ArrayList<Result>();if(d.nodes()!=null)d.nodes().stream().filter(n->matches(q,n.label(),n.description(),n.type())).forEach(n->r.add(new Result("node",n.id(),pid,n.label(),n.description())));if(d.edges()!=null)d.edges().stream().filter(e->matches(q,e.label(),e.type(),e.properties()==null?null:String.valueOf(e.properties().get("description")))).forEach(e->r.add(new Result("edge",e.id(),pid,e.label(),e.type())));findings.findAllByProjectId(pid).stream().filter(f->matches(q,f.getTitle())).forEach(f->r.add(new Result("finding",f.getId().toString(),pid,f.getTitle(),f.getDescription())));return r;}
}
